121		if err != nil {
122			return nil, status.Errorf(codes.InvalidArgument, "invalid share name: %v", err)
123		}
124		memoUID, shareToken := tokens[0], tokens[1]
125	
126		memo, err := s.Store.GetMemo(ctx, &store.FindMemo{UID: &memoUID})
127		if err != nil {
128			return nil, status.Errorf(codes.Internal, "failed to get memo")
129		}
130		if memo == nil {
131			return nil, status.Errorf(codes.NotFound, "memo not found")
132		}
133		if memo.CreatorID != user.ID && !isSuperUser(user) {
134			return nil, status.Errorf(codes.PermissionDenied, "permission denied")
135		}
